compile.workshop:
variables {
    global:
        0: g
}

subroutines {
    0: emptySub
    1: fullSub
}

rule ("Subroutine fullSub") {
    event {
        Subroutine;
        fullSub;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("calls") {
    event {
        Ongoing - Global;
    }
    actions {
        Call Subroutine(emptySub);
        Call Subroutine(fullSub);
    }
}

